use clap::ArgMatches;

// Four lookup tables generated by build script (see "gen_name_tables()" in "build.rs")
include!(concat!(env!("OUT_DIR"), "/codegen_name.rs"));

// + 14C -> 500, 64C, 798, 8E4, A30, B7C, CC8
const NAME_ADDRESS: u32 = 0x0200_0500;
const PC_NAMES: [&str; 7] = ["罗宾", "杰拉德", "伊万", "梅雅莉", "加西亚", "加斯敏", "西芭"];
// 23, 24, 3C, 3D, 3E, 40, 5B, 5C, 5D, 5E, 7B, 7C, 7D
const SPECIAL_CHARS: [char; 13] = ['#', '$', '<', '=', '>', '@', '[', '￥', ']', '^', '{', '|', '}'];

pub fn run(sub_matches: &ArgMatches) {
  let mut character_index = 0;

  if let Some(str) = sub_matches.get_one::<String>(PC_NAMES[character_index]) {
    print_result(str, character_index);
  }

  character_index += 1;
  if let Some(str) = sub_matches.get_one::<String>(PC_NAMES[character_index]) {
    print_result(str, character_index);
  }

  character_index += 1;
  if let Some(str) = sub_matches.get_one::<String>(PC_NAMES[character_index]) {
    print_result(str, character_index);
  }

  character_index += 1;
  if let Some(str) = sub_matches.get_one::<String>(PC_NAMES[character_index]) {
    print_result(str, character_index);
  }

  character_index += 1;
  if let Some(str) = sub_matches.get_one::<String>(PC_NAMES[character_index]) {
    print_result(str, character_index);
  }

  character_index += 1;
  if let Some(str) = sub_matches.get_one::<String>(PC_NAMES[character_index]) {
    print_result(str, character_index);
  }

  character_index += 1;
  if let Some(str) = sub_matches.get_one::<String>(PC_NAMES[character_index]) {
    print_result(str, character_index);
  }
}

fn is_valid_size(str: &str) -> bool {
  str.chars().count() <= 5
}


fn print_result(str: &str, index: usize) {
  let mut result_str = String::new();
  let pc_name = PC_NAMES[index].to_string();

  if !is_valid_size(str) {
    result_str.push_str(format!("{pc_name}的名字不能超过5个字符！\n\n\n").as_str());
    print!("{result_str}");
    return;
  }

  result_str.push_str(format!("{pc_name}\n").as_str());
  let char_vec: Vec<char> = str.chars().collect();
  let mut invalid_flag = false;
  let mut name_bytes = [0; 10];
  let mut name_index = 0;

  result_str.push_str("起名界面的输入方式：\n");
  for c in char_vec {
    if BASE_CHARACTERS_MAP.contains_key(&c) && !SPECIAL_CHARS.contains(&c) {
      let num = BASE_CHARACTERS_MAP.get(&c).unwrap();
      name_bytes[name_index] = *num;
      name_index += 1;

      result_str.push_str(format!("{c}：{c}\n").as_str());
    } else if DAKUTEN_KANA_MAP.contains_key(&c) {
      let string_value = DAKUTEN_KANA_MAP.get(&c).unwrap();

      for value in string_value.chars() {
        let num = BASE_CHARACTERS_MAP.get(&value).unwrap();
        name_bytes[name_index] = *num;
        name_index += 1;
      }

      result_str.push_str(format!("{}：{}\n", c, DAKUTEN_KANA_MAP.get(&c).unwrap()).as_str());
    } else if COMMON_HANZI_MAP.contains_key(&c) {
      let string_value = COMMON_HANZI_MAP.get(&c).unwrap();

      for value in string_value.chars() {
        let num = BASE_CHARACTERS_MAP.get(&value).unwrap();
        name_bytes[name_index] = *num;
        name_index += 1;
      }

      result_str.push_str(format!("{}：{}\n", c, COMMON_HANZI_MAP.get(&c).unwrap()).as_str());
    } else if SPECIAL_HANZI_MAP.contains_key(&c) {
      let num = SPECIAL_HANZI_MAP.get(&c).unwrap();
      let num_bytes = num.to_be_bytes();
      name_bytes[name_index] = num_bytes[0];
      name_bytes[name_index + 1] = num_bytes[1];
      name_index += 2;

      result_str.push_str(format!("{}：汉化版字库中包含该字符，但无法在游戏中正常输入，码值为{}\n", c, SPECIAL_HANZI_MAP.get(&c).unwrap()).as_str());
    } else if SPECIAL_CHARS.contains(&c) {
      invalid_flag = true;
      result_str.push_str(format!("{c}：汉化版的控制符，不能单独使用！\n").as_str());
    } else {
      invalid_flag = true;
      result_str.push_str(format!("{c}：汉化版字库中不包含该字符！\n").as_str());
    }
  }

  if invalid_flag {
    result_str.push_str(format!("由于存在不可用的字符，故不展示{pc_name}自定义名字所对应的十六进制值和金手指！\n").as_str());
  } else {
    result_str.push_str("十六进制值：\n");
    let len = name_bytes.len();
    for (i, name_byte) in name_bytes.iter().enumerate(){
      if i + 1 == len {
        result_str.push_str(format!("{name_byte:02X}\n").as_str());
      } else {
        result_str.push_str(format!("{name_byte:02X} ").as_str());
      }
    }

    result_str.push_str("金手指：\n");
    for i in 0..3 {
      if i == 2 {
        let j = i as usize;
        let address = NAME_ADDRESS + u32::try_from(index).unwrap() * 0x14C + i * 4;
        let value = u16::from_le_bytes([name_bytes[j * 4], name_bytes[j * 4 + 1]]);
        result_str.push_str(format!("{address:08X}:{value:04X}\n").as_str());
      } else {
        let j = i as usize;
        let address = NAME_ADDRESS + u32::try_from(index).unwrap() * 0x14C + i * 4;
        let value = u32::from_le_bytes([name_bytes[j * 4], name_bytes[j * 4 + 1], name_bytes[j * 4 + 2], name_bytes[j * 4 + 3]]);
        result_str.push_str(format!("{address:08X}:{value:08X}\n").as_str());
      }
    }
  }
  result_str.push_str("\n\n");
  print!("{result_str}");
}
